-- Fail loudly if any source had no active version: the NOT NULL would abort
-- anyway, but naming the cause beats reading a constraint violation.
do $$
declare missing int;
begin
  select count(*) into missing
  from (values ('https://www.canada.ca/en/immigration-refugees-citizenship/services/work-canada.html'), ('https://www.canada.ca/en/immigration-refugees-citizenship/services/work-canada/permit-outside.html'), ('https://www.canada.ca/en/immigration-refugees-citizenship/services/application/application-forms-guides/imm1295.html'), ('https://ircc.canada.ca/english/information/fees/fees.asp'), ('https://www.canada.ca/en/immigration-refugees-citizenship/services/work-canada/permit-outside/eligibility.html'), ('https://www.canada.ca/en/immigration-refugees-citizenship/services/work-canada/permit-outside/forms-documents.html'), ('https://www.canada.ca/en/immigration-refugees-citizenship/services/application/application-forms-guides/guide-5487-applying-work-permit-outside-canada.html'), ('https://www.canada.ca/en/immigration-refugees-citizenship/services/application/application-forms-guides/imm5645.html'), ('https://www.canada.ca/en/immigration-refugees-citizenship/services/application/medical-police/medical-exams/requirements-temporary-residents/country-requirements.html'), ('https://www.canada.ca/en/immigration-refugees-citizenship/services/work-canada/special-instructions/spouses-dependent-children/apply.html')) as r(url)
  where not exists (
    select 1 from public.visa_source_versions v
      join public.visa_sources s on s.id = v.source_id
     where s.source_url = r.url and v.is_active
  );
  if missing > 0 then
    -- Replay-aware. 20260820170000 installs the fixture table for the duration
    -- of the chain, so its presence means this is a database being rebuilt from
    -- empty. An authority that blocks our egress (migri.fi, immi.homeaffairs)
    -- has no version to bind to and never will, and the skipped rows are
    -- recorded in visa_requirement_bootstrap_skips. Outside a replay this stays
    -- fatal, which is the point: in normal operation a missing version means
    -- the sync has not run and the extraction is premature.
    if to_regclass('public.visa_source_version_fixtures') is not null then
      raise warning '% source(s) have no active version; their requirements were skipped (replay)', missing;
    else
      raise exception '% source(s) have no active version. Run the sync before extracting requirements.', missing;
    end if;
  end if;
end $$;

commit;

-- 35 requirement(s): 7 condition, 18 evidence, 4 form, 3 step, 3 fee
